import { sqliteTable, text, integer, primaryKey, index } from 'drizzle-orm/sqlite-core';

// Generated by Better Auth. Run `pnpm run auth:generate` to update these
// tables instead of editing them directly, such as after adding an auth plugin.

export const user = sqliteTable('user', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  email: text('email').notNull().unique(),
  emailVerified: integer('email_verified', { mode: 'boolean' })
    .notNull()
    .default(false),
  image: text('image'),
  createdAt: integer('created_at', { mode: 'timestamp' })
    .notNull()
    .$defaultFn(() => new Date()),
  updatedAt: integer('updated_at', { mode: 'timestamp' })
    .notNull()
    .$defaultFn(() => new Date()),
  role: text('role'),
  banned: integer('banned', { mode: 'boolean' }).default(false),
  banReason: text('ban_reason'),
  banExpires: integer('ban_expires', { mode: 'timestamp' })
});

export const session = sqliteTable('session', {
  id: text('id').primaryKey(),
  expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
  token: text('token').notNull().unique(),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull(),
  ipAddress: text('ip_address'),
  userAgent: text('user_agent'),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  impersonatedBy: text('impersonated_by')
});

export const account = sqliteTable('account', {
  id: text('id').primaryKey(),
  accountId: text('account_id').notNull(),
  providerId: text('provider_id').notNull(),
  userId: text('user_id')
    .notNull()
    .references(() => user.id, { onDelete: 'cascade' }),
  accessToken: text('access_token'),
  refreshToken: text('refresh_token'),
  idToken: text('id_token'),
  accessTokenExpiresAt: integer('access_token_expires_at', {
    mode: 'timestamp'
  }),
  refreshTokenExpiresAt: integer('refresh_token_expires_at', {
    mode: 'timestamp'
  }),
  scope: text('scope'),
  password: text('password'),
  createdAt: integer('created_at', { mode: 'timestamp' }).notNull(),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).notNull()
});

export const verification = sqliteTable('verification', {
  id: text('id').primaryKey(),
  identifier: text('identifier').notNull(),
  value: text('value').notNull(),
  expiresAt: integer('expires_at', { mode: 'timestamp' }).notNull(),
  createdAt: integer('created_at', { mode: 'timestamp' }).$defaultFn(
    () => new Date()
  ),
  updatedAt: integer('updated_at', { mode: 'timestamp' }).$defaultFn(
    () => new Date()
  )
});

export const workspace = sqliteTable('workspace', {
  id: text('id').primaryKey(),
  name: text('name').notNull(),
  createdAt: integer('created_at').notNull(),
});

export const membership = sqliteTable('membership', {
  workspaceId: text('workspace_id').notNull().references(() => workspace.id, { onDelete: 'cascade' }),
  userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
  role: text('role', { enum: ['owner', 'member'] }).notNull(),
}, (table) => [primaryKey({ columns: [table.workspaceId, table.userId] }), index('membership_user_idx').on(table.userId)]);

export const invitation = sqliteTable('invitation', {
  id: text('id').primaryKey(),
  workspaceId: text('workspace_id').notNull().references(() => workspace.id, { onDelete: 'cascade' }),
  email: text('email').notNull(),
  tokenHash: text('token_hash').notNull().unique(),
  expiresAt: integer('expires_at').notNull(),
  acceptedAt: integer('accepted_at'),
});

export const board = sqliteTable('board', {
  id: text('id').primaryKey(),
  workspaceId: text('workspace_id').notNull().references(() => workspace.id, { onDelete: 'cascade' }),
  name: text('name').notNull(),
  description: text('description').notNull().default(''),
  visibility: text('visibility', { enum: ['private', 'public'] }).notNull().default('private'),
  archived: integer('archived', { mode: 'boolean' }).notNull().default(false),
  color: text('color').notNull().default('coral'),
  createdAt: integer('created_at').notNull(),
}, (table) => [index('board_workspace_idx').on(table.workspaceId)]);

export const boardList = sqliteTable('board_list', {
  id: text('id').primaryKey(),
  boardId: text('board_id').notNull().references(() => board.id, { onDelete: 'cascade' }),
  name: text('name').notNull(),
  position: integer('position').notNull(),
}, (table) => [index('list_board_idx').on(table.boardId)]);

export type ChecklistItem = { id: string; title: string; done: boolean };

export const card = sqliteTable('card', {
  id: text('id').primaryKey(),
  boardId: text('board_id').notNull().references(() => board.id, { onDelete: 'cascade' }),
  listId: text('list_id').notNull().references(() => boardList.id, { onDelete: 'cascade' }),
  title: text('title').notNull(),
  description: text('description').notNull().default(''),
  position: integer('position').notNull(),
  labels: text('labels', { mode: 'json' }).$type<string[]>().notNull().default([]),
  assignees: text('assignees', { mode: 'json' }).$type<string[]>().notNull().default([]),
  dueDate: text('due_date'),
  priority: text('priority', { enum: ['urgent', 'high', 'medium', 'low', 'none'] }).notNull().default('none'),
  checklist: text('checklist', { mode: 'json' }).$type<ChecklistItem[]>().notNull().default([]),
  cover: text('cover'),
  archived: integer('archived', { mode: 'boolean' }).notNull().default(false),
  createdAt: integer('created_at').notNull(),
}, (table) => [index('card_board_idx').on(table.boardId), index('card_list_idx').on(table.listId)]);

export const comment = sqliteTable('comment', {
  id: text('id').primaryKey(),
  cardId: text('card_id').notNull().references(() => card.id, { onDelete: 'cascade' }),
  userId: text('user_id').notNull().references(() => user.id, { onDelete: 'cascade' }),
  body: text('body').notNull(),
  createdAt: integer('created_at').notNull(),
}, (table) => [index('comment_card_idx').on(table.cardId)]);

export const activity = sqliteTable('activity', {
  id: text('id').primaryKey(),
  boardId: text('board_id').notNull().references(() => board.id, { onDelete: 'cascade' }),
  cardId: text('card_id').references(() => card.id, { onDelete: 'cascade' }),
  userId: text('user_id').references(() => user.id, { onDelete: 'set null' }),
  message: text('message').notNull(),
  createdAt: integer('created_at').notNull(),
}, (table) => [index('activity_board_idx').on(table.boardId)]);
